<template>
 <div class="pattern-tools">
  <b-button variant="outline-secondary" size="sm" class="pattern-nav-button" @click="openManager">Patterns <span class="pattern-nav-count">{{ activeCount }}</span></b-button>
  <b-modal id="patternsManager" title="Search patterns" size="xl" scrollable hide-footer @show="refresh">
   <b-alert :show="!!error" variant="danger" role="alert">{{ error }}</b-alert>
   <div class="patterns-manager-heading"><p class="text-muted mb-0">Highlight important traffic and exclude noise.</p><b-button variant="primary" @click="edit(null)">+ New pattern</b-button></div>
   <div class="pattern-summary"><div><strong>{{ patterns.length }}</strong><span>Total patterns</span></div><div><strong class="text-success">{{ activeCount }}</strong><span>Active now</span></div><div><strong>{{ patterns.length-activeCount }}</strong><span>Paused</span></div></div>
   <section class="pattern-filter-panel" aria-label="Pattern search and filters">
    <label for="patterns-search">Find a pattern</label><b-form-input id="patterns-search" v-model="query" placeholder="Name, expression or group" aria-label="Search patterns"/>
    <div class="pattern-filter-grid"><div><label for="patterns-group-filter">Group</label><b-form-select id="patterns-group-filter" v-model="group" :options="groupOptions" aria-label="Filter by group"/></div><div><label for="patterns-service-filter">Service</label><b-form-select id="patterns-service-filter" v-model="service" :options="serviceOptions" aria-label="Filter by service"/></div><div><label for="patterns-status-filter">State</label><b-form-select id="patterns-status-filter" v-model="status" :options="[{value:'all',text:'Any status'},{value:'enabled',text:'Enabled'},{value:'disabled',text:'Disabled'}]" aria-label="Filter by state"/></div><div><label for="patterns-action-filter">Action</label><b-form-select id="patterns-action-filter" v-model="action" :options="[{value:'all',text:'Any action'},{value:'FIND',text:'Search'},{value:'IGNORE',text:'Exclude sessions'}]" aria-label="Filter by action"/></div></div>
    <b-button v-if="query||group!=='*'||service!=='*'||status!=='all'||action!=='all'" size="sm" variant="link" class="mt-2 p-0" @click="clearManagerFilters">Reset pattern filters</b-button>
   </section>
   <div class="patterns-selection"><b-button size="sm" variant="outline-secondary" @click="selectFiltered" :disabled="!filtered.length">{{ allSelected?'Clear selection':'Select matching' }}</b-button><span class="small text-muted">{{ filtered.length }} found<span v-if="selected.length"> · {{ selected.length }} selected</span></span><template v-if="selected.length"><b-button size="sm" variant="outline-success" :disabled="busy" @click="bulk('enable')">Enable</b-button><b-button size="sm" variant="outline-secondary" :disabled="busy" @click="bulk('disable')">Disable</b-button><b-button size="sm" variant="outline-danger" :disabled="busy" @click="bulk('delete')">Delete</b-button></template></div>
   <div v-if="filtered.length" class="table-responsive"><table class="table pattern-table"><thead><tr><th scope="col" aria-label="Selection"></th><th scope="col">Pattern</th><th scope="col">Search scope</th><th scope="col">State</th><th scope="col" class="text-right">Actions</th></tr></thead><tbody>
    <tr v-for="p in pageItems" :key="p.id">
     <td><input type="checkbox" v-model="selected" :value="p.id" :aria-label="'Select '+p.name"/></td>
     <td><div class="pattern-name"><span class="color-dot" :style="{backgroundColor:p.color}"/><strong>{{ p.name }}</strong><span v-if="p.group" class="pattern-group">{{ p.group }}</span></div><div class="pattern-expression" :title="p.value">{{ p.value }}</div><small class="text-muted">{{ {SUBSTRING:'Exact text',REGEX:'Regex',SUBBYTES:'HEX'}[p.searchType] }} · {{ p.actionType==='IGNORE'?'Hide session':'Highlight match' }}</small></td>
     <td><span>{{ serviceName(p.serviceId) }}</span><div class="small text-muted">{{ {INPUT:'Requests',OUTPUT:'Responses',BOTH:'Requests and responses'}[p.directionType] }}</div></td>
     <td><b-form-checkbox :checked="p.enabled" switch :disabled="busy" @change="toggle(p,$event)" :aria-label="'Enabled: '+p.name">{{ p.enabled?'Enabled':'Disabled' }}</b-form-checkbox></td>
     <td><div class="pattern-actions"><b-button size="sm" variant="outline-primary" :disabled="busy" @click="edit(p)">Edit</b-button><b-dropdown text="More" size="sm" variant="outline-secondary" right boundary="viewport" :disabled="busy" :aria-label="'Actions: '+p.name"><b-dropdown-item-button v-if="p.actionType==='FIND'" @click="filter(p)">Show sessions</b-dropdown-item-button><b-dropdown-item-button @click="duplicate(p)">Duplicate</b-dropdown-item-button><b-dropdown-item-button @click="lookback(p)">Search history</b-dropdown-item-button><b-dropdown-divider/><b-dropdown-item-button variant="danger" @click="remove(p)">Delete</b-dropdown-item-button></b-dropdown></div></td>
    </tr>
   </tbody></table></div>
   <div v-else class="pattern-manager-empty"><h6>{{ patterns.length?'No matching patterns':'Create your first pattern' }}</h6><p>{{ patterns.length?'Change your search or reset the filters.':'Add a flag, text fragment or byte sequence.' }}</p><b-button variant="outline-primary" @click="patterns.length?clearManagerFilters():edit(null)">{{ patterns.length?'Reset filters':'Create pattern' }}</b-button></div>
   <b-pagination v-if="filtered.length>20" v-model="page" :total-rows="filtered.length" :per-page="20" align="center" aria-label="Pattern pages"/>
   <div class="pattern-manager-footer"><span>New rules apply immediately. Search history checks saved traffic.</span><b-button v-if="$route.query.pattern||$route.query.patterns" size="sm" variant="link" @click="resetFilter">Show all sessions</b-button><b-button variant="outline-secondary" size="sm" @click="$bvModal.hide('patternsManager')">Close</b-button></div>
  </b-modal>
  <PatternModal :creating="creating" :initial-pattern="editing" @patternAddComplete="refresh"/>
  <LookBack :pattern-id="lookbackID"/>
 </div>
</template>
<script>
import {filterLocation} from '../trafficFilters.mjs';
import PatternModal from '@/views/PatternModal';import LookBack from '@/views/LookBack';
const message=e=>e.response?.data?.error||e.message;
export default {
 components:{PatternModal,LookBack},data:()=>({query:'',group:'*',service:'*',status:'all',action:'all',selected:[],page:1,creating:true,editing:{},lookbackID:0,error:'',busy:false}),
 computed:{patterns(){return this.$store.state.patterns.filter(p=>!p.deleted)},activeCount(){return this.patterns.filter(p=>p.enabled).length},groupOptions(){return [{value:'*',text:'All groups'},{value:'',text:'No group'},...[...new Set(this.patterns.map(p=>p.group).filter(Boolean))].sort().map(g=>({value:g,text:g}))]},serviceOptions(){return [{value:'*',text:'Any service'},{value:'global',text:'Global patterns'},...this.$store.state.services.map(s=>({value:String(s.port),text:s.name}))]},filtered(){const q=this.query.toLowerCase();return this.patterns.filter(p=>`${p.name} ${p.value} ${p.group||''}`.toLowerCase().includes(q)&&(this.group==='*'||(p.group||'')===this.group)&&(this.service==='*'||this.service==='global'&&p.serviceId==null||String(p.serviceId)===this.service)&&(this.status==='all'||p.enabled===(this.status==='enabled'))&&(this.action==='all'||p.actionType===this.action)).sort((a,b)=>(a.group||'').localeCompare(b.group||'')||a.name.localeCompare(b.name))},pageItems(){return this.filtered.slice((this.page-1)*20,this.page*20)},allSelected(){return this.filtered.length>0&&this.filtered.every(p=>this.selected.includes(p.id))}},
 watch:{query:'resetPage',group:'resetPage',service:'resetPage',status:'resetPage',action:'resetPage',patterns(){const ids=new Set(this.patterns.map(p=>p.id));this.selected=this.selected.filter(id=>ids.has(id));this.page=Math.min(this.page,Math.max(1,Math.ceil(this.filtered.length/20)))}},
 methods:{
  clearManagerFilters(){this.query='';this.group='*';this.service='*';this.status='all';this.action='all';this.resetPage()},
  openManager(){this.$bvModal.show('patternsManager')},async refresh(){try{this.$store.commit('setPatterns',(await this.$http.get('/pattern/')).data)}catch(e){this.error=message(e)}},resetPage(){this.page=1;this.selected=[]},
  edit(p){this.creating=!p;this.editing=p?{...p}:{};this.$nextTick(()=>this.$bvModal.show('patternModal'))},duplicate(p){this.creating=true;this.editing={...p,id:0,name:p.name+' — copy'};this.$nextTick(()=>this.$bvModal.show('patternModal'))},
  serviceName(id){return id==null?'All services':this.$store.state.services.find(s=>s.port===id)?.name||`Port ${id}`},
  selectFiltered(){this.selected=this.allSelected?[]:this.filtered.map(p=>p.id)},
  async toggle(p,enabled){const previous=p.enabled;this.busy=true;this.error='';this.$store.commit('setPatterns',this.$store.state.patterns.map(x=>x.id===p.id?{...x,enabled}:x));try{await this.$http.post(`/pattern/${p.id}/enable`,null,{params:{enabled}});await this.refresh()}catch(e){this.$store.commit('setPatterns',this.$store.state.patterns.map(x=>x.id===p.id?{...x,enabled:previous}:x));this.error=message(e)}finally{this.busy=false}},
  async bulk(action){if(action==='delete'&&!await this.$bvModal.msgBoxConfirm(`Delete selected patterns (${this.selected.length})? Traffic will remain in history.`,{title:'Delete patterns?',okTitle:'Delete',cancelTitle:'Cancel',okVariant:'danger'}))return;this.busy=true;this.error='';try{await this.$http.post('/v2/patterns-bulk',{ids:this.selected,action});this.selected=[];await this.refresh()}catch(e){this.error=message(e)}finally{this.busy=false}},
  async remove(p){if(!await this.$bvModal.msgBoxConfirm(`Delete pattern “${p.name}”?`,{title:'Delete pattern',okTitle:'Delete',cancelTitle:'Cancel',okVariant:'danger'}))return;this.busy=true;try{await this.$http.delete(`/pattern/${p.id}`);await this.refresh()}catch(e){this.error=message(e)}finally{this.busy=false}},
  lookback(p){this.lookbackID=p.id;this.$bvModal.show('lookBackModal')},filter(p){this.$router.push(filterLocation(this.$route,{patterns:[p.id]}),()=>{});this.$bvModal.hide('patternsManager')},resetFilter(){this.$router.push(filterLocation(this.$route,{patterns:[]}),()=>{});this.$bvModal.hide('patternsManager')},
 }
}
</script>
<style scoped>
.pattern-tools{flex-shrink:0}.pattern-nav-button{display:flex;gap:6px;align-items:center}.pattern-nav-count{border-radius:4px;background:var(--gm-accent-soft);color:var(--gm-accent);padding:0 5px;font-size:12px;font-weight:700}.patterns-manager-heading{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:8px;margin-bottom:10px;font-size:12px}
.pattern-summary{display:flex;flex-wrap:wrap;gap:6px 16px;margin-bottom:10px;font-size:12px}.pattern-summary>div{display:flex;gap:5px;align-items:baseline}.pattern-summary strong{font-size:14px;line-height:1.25;font-weight:650}.pattern-summary span{color:var(--gm-muted)}.pattern-filter-panel{padding:10px;background:var(--gm-panel-alt);border:1px solid var(--gm-border);border-radius:8px}.pattern-filter-panel label{font-size:12px;font-weight:600;margin-bottom:3px}.pattern-filter-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-top:8px}.patterns-selection{display:flex;gap:6px;align-items:center;flex-wrap:wrap;padding:10px 0}
.pattern-table th{font-size:11px;letter-spacing:.03em;text-transform:uppercase;color:var(--gm-muted);white-space:nowrap}.pattern-table th,.pattern-table td{padding:8px;vertical-align:middle}.pattern-table td:first-child{width:30px}.pattern-table input[type=checkbox]{width:16px;height:16px;accent-color:var(--gm-accent)}.pattern-name{display:flex;flex-wrap:wrap;gap:5px;align-items:center;overflow-wrap:anywhere}.color-dot{width:7px;height:7px;border-radius:50%;flex-shrink:0}.pattern-group{background:var(--gm-panel-alt);border:1px solid var(--gm-border);font-size:11px;border-radius:4px;padding:0 4px}.pattern-expression{font-family:var(--gm-mono);white-space:pre-wrap;overflow-wrap:anywhere;max-width:360px;max-height:50px;overflow:auto;margin:3px 0;font-size:12px;color:var(--gm-muted)}.pattern-actions{display:flex;justify-content:flex-end;gap:6px;white-space:nowrap}.pattern-manager-empty{text-align:center;padding:24px 12px;border:1px dashed var(--gm-border);border-radius:8px;margin:4px 0 10px}.pattern-manager-empty p{color:var(--gm-muted);font-size:12px}.pattern-manager-footer{border-top:1px solid var(--gm-border);padding-top:10px;display:flex;gap:8px;align-items:center;justify-content:space-between;flex-wrap:wrap}.pattern-manager-footer>span{font-size:12px;color:var(--gm-muted);flex:1;min-width:180px}
@media(max-width:767px){
 .pattern-filter-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.pattern-table,.pattern-table tbody{display:block;width:100%}.pattern-table thead{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}
 .pattern-table tr{display:grid;grid-template-columns:24px minmax(0,1fr);gap:6px 4px;padding:10px 0;border-top:1px solid var(--gm-border)}.pattern-table td{display:block;border:0;padding:0;min-width:0}.pattern-table td:first-child{width:auto;grid-column:1;grid-row:1}.pattern-table td:nth-child(n+2){grid-column:2}.pattern-table td:nth-child(3){font-size:12px;overflow-wrap:anywhere}.pattern-table td:nth-child(3)>div{display:inline;margin-left:6px}.pattern-table td:nth-child(4){grid-column:2}.pattern-expression{max-width:none}.pattern-actions{justify-content:flex-start}.pattern-summary{gap:4px 12px}
}
</style>
